import { HttpError, body, route } from '../_lib/http.js'
import { redis } from '../_lib/redis.js'
import { requireSession } from '../_lib/session.js'
import { MAX_PHOTO_B64, PHOTO_KEY, SYNC } from '../_lib/sync.js'

/**
 * GET → the JPEG for a journal photo. PUT {data: base64 JPEG} stores it (≈400 KB max).
 * Keys are generated by the app per photo version, so a replaced photo gets a new key.
 */
export default route(['GET', 'PUT'], async (req, res) => {
  requireSession(req)
  const key = String(req.query.key ?? '')
  if (!PHOTO_KEY.test(key)) throw new HttpError(400, 'Invalid photo key')
  if (req.method === 'PUT') {
    const data = body<{ data?: unknown }>(req).data
    if (typeof data !== 'string' || !/^[A-Za-z0-9+/=]+$/.test(data)) throw new HttpError(400, 'Invalid photo data')
    if (data.length > MAX_PHOTO_B64) throw new HttpError(413, 'That photo is too large to sync.')
    if (!Buffer.from(data.slice(0, 8), 'base64').subarray(0, 3).equals(Buffer.from([0xff, 0xd8, 0xff]))) throw new HttpError(400, 'Photos must be JPEG')
    await redis().set(SYNC.photo(key), data)
    return { ok: true }
  }
  const data = await redis().get<string>(SYNC.photo(key))
  if (!data) throw new HttpError(404, 'Photo not found')
  res.setHeader('Content-Type', 'image/jpeg')
  res.setHeader('Cache-Control', 'private, max-age=31536000, immutable')
  res.status(200).send(Buffer.from(data, 'base64'))
})
